import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"60、【節】 兌下坎上","description":"周易口訣義 - 60、【節】 兌下坎上","frontmatter":{"title":"60、【節】 兌下坎上","description":"周易口訣義 - 60、【節】 兌下坎上"},"headers":[],"relativePath":"classics/koujueyi/062.md","filePath":"classics/koujueyi/062.md"}'),r={name:"classics/koujueyi/062.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_60、【節】-兌下坎上" tabindex="-1">60、【節】 兌下坎上 <a class="header-anchor" href="#_60、【節】-兌下坎上" aria-label="Permalink to “60、【節】 兌下坎上”">​</a></h1><p>彖曰：「節亨」，剛柔分而剛得中。「苦節不可貞」，其道窮也。說以行險，當位以節，中正以通。天地節而四時成，節以制度，不傷財，不害民。</p><p>象曰：澤上有水，節。君子以制數度，議德行。</p><p>初九：不出戶庭，無咎。</p><p>象曰：「不出戶庭」，知通塞也。</p><p>九二：不出門庭，兇。</p><p>象曰：「不出門庭兇」，失時極也。</p><p>六三：不節若，則嗟若，無咎。</p><p>象曰：「不節」之「嗟」，又誰咎也。</p><p>六四：安節，亨。</p><p>象曰：「安節」之「亨」，承上道也。</p><p>九五，甘節，吉，往有尚。</p><p>象曰：「甘節」之「吉」，居位中也。</p><p>上六，苦節，貞兇，悔亡。</p><p>象曰「苦節貞兇」，其道窮也。</p><p>解讀</p><p>「節，亨」者，節，制度之名，節止之義，故謂之「節」也。節制要在得宜，尊卑有別，其道乃通，故曰「節亨」也。「苦節，不可貞」者，為節之道，必須當理，若過刻薄，傷於物情，物所不堪，非為節道，不可為正，故「苦節不可貞」也。象曰「澤上有水，節」者，「澤」，陂陷之處也。澤之大小，各有區別，今水居節上，隨其大小得宜，各有止節，故為節象也。「君子以制數度，議德行」者，「數」謂禮數等差也，「度」謂上下優劣也。議人德行，輕重得宜，是皆節制度數之義，所以周禮五等諸侯所受錫命，皆有度數是也。</p><p>「初九，不出戶庭，無咎」者，節者，制度之義。今初九處節之初，即是初製法度，宜其慎密，不令洩露。若教令未宣而乃洩露，即人心多險，奸詐生焉。若慎密不失，施制合宜，應時無偽，乃得「無咎」，知通塞矣。</p><p>「九二，不出門庭，兇」者，初為制度之始，法制未成，固宜慎密。今至九二，是法制已成，而猶溺之，失時之中，乃乖於理，失時之極，所以致兇，故曰「不出門庭，兇」也。</p><p>「六三，不節若，則嗟若，無咎」者，處節之時，故宜各得其序，不相乖越。今六三以陰居陽，以柔乘剛，以為驕僭而不為節，禍將及身，以至哀嗟，故曰「不節若」也。禍自己招，非人所與，無所怨咎於人，故曰「無咎」。</p><p>「六四，安節，亨」者，以柔得位，承順於君，是得節之道，但稱安行此節而不改變，則何往不通？故曰「安節，亨」也。</p><p>「九五，甘節，吉，往有尚」者，不苦而美謂之甘也。九五為節之主，履正居中，節以制度，不傷財，不害人，為節而無傷，即是不苦而甘，所以甘吉矣；為節不傷，苦而能甘，以此而往，人所嘉尚，故曰「往有尚」也。</p><p>「上六，苦節，貞兇，悔亡」者，居節之極，是過節之中，傷於為正，物所不堪，正之兇矣，故曰「苦節貞兇」。若以施人，則是正道，兇；若以苦節於身，修己自厲，則可以「悔亡」矣。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
